// Approval receipts (docs/approval-receipts.md): the canonical JSON writer, the policy field, the payload rules, the
// signature, the wire form and the reference verifier, plus the committed test vectors the hub's verifier tests
// against (test/fixtures/approval-receipts/vectors.json, regenerated by scripts/gen-receipt-vectors.mjs).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash, createPrivateKey, createPublicKey, verify as edVerify, sign as edSign } from "node:crypto";
import { canonicalJson } from "../cli/canonical-json.mjs";
import * as R from "../cli/approval-receipts.mjs";
import { buildVectors } from "../scripts/gen-receipt-vectors.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const PKCS8_ED25519 = Buffer.from("302e020100300506032b657004220420", "hex");
const keyFromSeed = (label) => createPrivateKey({ key: Buffer.concat([PKCS8_ED25519, createHash("sha256").update(label).digest()]), format: "der", type: "pkcs8" });
const KEY = keyFromSeed("approval-receipts-unit");
const PUB = createPublicKey(KEY);
const signer = (k = KEY) => ({ sign: (bytes) => edSign(null, bytes, k), publicKey: createPublicKey(k) });
// One key per source: trust comes from the pinned key's keySource, never from the payload's.
const CONSOLE_KEY = keyFromSeed("approval-receipts-unit-console");
const HELPER_KEY = keyFromSeed("approval-receipts-unit-helper");
const pin = (k, keySource) => ({ keyId: R.receiptKeyId(createPublicKey(k)), publicKey: R.rawPublicKey(createPublicKey(k)), keySource });
const pinned = [pin(KEY, "device"), pin(CONSOLE_KEY, "console"), pin(HELPER_KEY, "helper")];
const NOW = 1790000000;
const ARGS = { device: "lab-01", command: "whoami" };
const base = (over = {}) => ({ aud: "hub-test", tool: "run_command", input: ARGS, device: "h2:0011223344556677", session: "h2:8899aabbccddeeff", nonce: "0123456789abcdef0123456789abcdef", iat: NOW, ttlSec: 60, basis: "allowed", keySource: "device", ...over });

test("canonical JSON: keys sorted recursively, no whitespace, numbers and strings as JSON.stringify writes them", () => {
  assert.equal(canonicalJson({ b: 1, a: { d: [3, { z: true, y: null }], c: "x" } }), '{"a":{"c":"x","d":[3,{"y":null,"z":true}]},"b":1}');
  assert.equal(canonicalJson({ n: 30, f: 0.1, e: 1e21, s: 1e-7, z: -0, big: 9007199254740994 }), '{"big":9007199254740994,"e":1e+21,"f":0.1,"n":30,"s":1e-7,"z":0}');
  assert.equal(canonicalJson({ u: "héllo ✓", c: "a\u0001\n\t\"\\/" }), '{"c":"a\\u0001\\n\\t\\"\\\\/","u":"héllo ✓"}');
  assert.equal(canonicalJson([]), "[]");
  assert.equal(canonicalJson({}), "{}");
});

test("policy field: audiences validated, ttlSec defaults to 60 and is capped at 120, absent field is null", () => {
  assert.equal(R.receiptPolicy({}), null);
  assert.equal(R.receiptPolicy(null), null);
  const warns = [];
  const warn = (m) => warns.push(m);
  const p = R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai", tools: ["run_*"] }] } }, { warn });
  assert.deepEqual(p, { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai", tools: ["run_*"] }], ttlSec: 60 });
  assert.equal(R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai" }], ttlSec: 300 } }, { warn }).ttlSec, 120);
  assert.equal(R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai" }], ttlSec: 120 } }, { warn }).ttlSec, 120);
  assert.equal(R.receiptPolicy({ approvalReceipts: { v: 2, audiences: [{ aud: "hub-1", mcpServer: "it-ai" }] } }, { warn }), null);
  assert.equal(R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [] } }, { warn }), null);
  // A malformed audience is dropped, the rest kept.
  const q = R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "", mcpServer: "x" }, { aud: "ok", mcpServer: "it-ai", tools: [] }, { aud: "hub-2", mcpServer: "it-ai" }] } }, { warn });
  assert.deepEqual(q.audiences, [{ aud: "hub-2", mcpServer: "it-ai" }]);
  assert.ok(warns.length >= 2);
  for (const w of warns) assert.ok(!w.includes("hub-1"), "a warning never echoes a value");
});

test("tool names: the mcp__<server>__ prefix is split off; a receipt names the bare tool", () => {
  assert.deepEqual(R.splitMcpTool("mcp__it-ai__run_command"), { server: "it-ai", tool: "run_command" });
  assert.deepEqual(R.splitMcpTool("mcp__plugin_kit_it-ai__run_command"), { server: "plugin_kit_it-ai", tool: "run_command" });
  assert.equal(R.splitMcpTool("Bash"), null);
  assert.equal(R.splitMcpTool("mcp__it-ai__"), null);
  const p = R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai", tools: ["run_*", "dissolve_agent"] }, { aud: "hub-2", mcpServer: "other" }] } });
  assert.deepEqual(R.matchAudience(p, "mcp__it-ai__run_command"), { aud: "hub-1", mcpServer: "it-ai", tool: "run_command" });
  assert.deepEqual(R.matchAudience(p, "mcp__it-ai__dissolve_agent"), { aud: "hub-1", mcpServer: "it-ai", tool: "dissolve_agent" });
  assert.equal(R.matchAudience(p, "mcp__it-ai__list_devices"), null, "a tool outside the globs gets no receipt");
  assert.equal(R.matchAudience(p, "mcp__it-ai__xrun_command"), null, "a glob is anchored");
  assert.deepEqual(R.matchAudience(p, "mcp__other__anything"), { aud: "hub-2", mcpServer: "other", tool: "anything" });
  assert.equal(R.matchAudience(p, "mcp__It-Ai__run_command"), null, "server names match exactly");
  assert.equal(R.matchAudience(p, "mcp__third__run_command"), null);
  assert.equal(R.matchAudience(null, "mcp__it-ai__run_command"), null);
  // The payload refuses a prefixed name.
  assert.equal(R.buildPayload(base({ tool: "mcp__it-ai__run_command" })), null);
});

test("reserved key: _moorai is stripped from the input (a copy) and left out of argsSha256", () => {
  const input = { ...ARGS, _moorai: { receipt: "forged.sig" } };
  const s = R.stripReserved(input);
  assert.equal(s.had, true);
  assert.deepEqual(s.value, ARGS);
  assert.ok("_moorai" in input, "the caller's object is not mutated");
  assert.deepEqual(R.stripReserved(ARGS), { value: ARGS, had: false });
  const want = createHash("sha256").update(canonicalJson(ARGS), "utf8").digest("hex");
  assert.equal(R.argsSha256(ARGS), want);
  assert.equal(R.argsSha256(input), want);
  assert.match(want, /^[0-9a-f]{64}$/);
});

test("payload: fixed field set, exp - iat at most 120, device receipts are basis allowed only", () => {
  const p = R.buildPayload(base());
  assert.deepEqual(Object.keys(p).sort(), ["argsSha256", "aud", "basis", "device", "exp", "iat", "keyId", "keySource", "nonce", "session", "tool", "typ", "v"]);
  assert.equal(p.v, 1);
  assert.equal(p.typ, "moorai.receipt");
  assert.equal(p.exp - p.iat, 60);
  assert.equal(R.buildPayload(base({ ttlSec: 120 })).exp - NOW, 120);
  assert.equal(R.buildPayload(base({ ttlSec: 121 })), null, "a lifetime over 120 s is refused");
  assert.equal(R.buildPayload(base({ ttlSec: 0 })), null);
  assert.equal(R.buildPayload(base({ basis: "approved", keySource: "device", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS" })), null, "device + approved is refused");
  assert.equal(R.buildPayload(base({ basis: "approved", keySource: "console" })), null, "approved needs an approvalId");
  assert.equal(R.buildPayload(base({ approvalId: "apr_0123456789ABCDEFGHJKMNPQRS" })), null, "approvalId only with approved");
  assert.equal(R.buildPayload(base({ approver: "h2:00aa" })), null, "approver only on console receipts");
  assert.equal(R.buildPayload(base({ nonce: "xyz" })), null);
  const c = R.buildPayload(base({ basis: "approved", keySource: "console", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS", approver: "h2:00aa11bb22cc33dd" }));
  assert.equal(c.approvalId, "apr_0123456789ABCDEFGHJKMNPQRS");
  assert.equal(c.approver, "h2:00aa11bb22cc33dd");
  assert.equal(R.buildPayload(base({ keySource: "helper" })).keySource, "helper", "helper is accepted by the schema");
});

test("signature: ed25519 over the UTF-8 bytes of the prefix plus canonical payload; wire is base64url(payload).base64url(sig)", () => {
  const wire = R.mintReceipt({ ...base(), signer: signer() });
  assert.match(wire, /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/);
  const [p64, s64] = wire.split(".");
  const payloadBytes = Buffer.from(p64, "base64url");
  const payload = JSON.parse(payloadBytes.toString("utf8"));
  assert.equal(payloadBytes.toString("utf8"), canonicalJson(payload), "the payload travels in canonical form");
  assert.equal(payload.keyId, R.receiptKeyId(PUB));
  const msg = Buffer.concat([Buffer.from("moorai-receipt|v1|", "utf8"), payloadBytes]);
  assert.ok(edVerify(null, msg, PUB, Buffer.from(s64, "base64url")));
  assert.ok(!edVerify(null, payloadBytes, PUB, Buffer.from(s64, "base64url")), "the prefix is part of the signed bytes");
  assert.deepEqual(R.signingInput(payload), msg);
  assert.ok(!p64.includes("=") && !s64.includes("="), "no padding");
});

test("key encoding: raw 32-byte public key as base64url without padding; keyId is sha256(raw key) first 32 hex", () => {
  const raw = R.rawPublicKey(PUB);
  assert.equal(Buffer.from(raw, "base64url").length, 32);
  assert.ok(!raw.includes("="));
  const spkiDer = PUB.export({ type: "spki", format: "der" });
  assert.equal(raw, spkiDer.subarray(12).toString("base64url"));
  assert.equal(R.receiptKeyId(PUB), createHash("sha256").update(spkiDer.subarray(12)).digest("hex").slice(0, 32));
  assert.equal(R.receiptKeyId(spkiDer.toString("base64")), R.receiptKeyId(PUB), "same id from a base64 SPKI string");
  assert.equal(R.receiptKeyId(raw), R.receiptKeyId(PUB), "same id from the raw base64url key");
});

test("verifier: every hub check", () => {
  const input = ARGS;
  const v = (wire, over = {}) => R.verifyReceipt(wire, { keys: pinned, aud: "hub-test", tool: "run_command", input, nowSec: NOW + 10, seen: new Set(), ...over });
  const console1 = R.mintReceipt({ ...base({ basis: "approved", keySource: "console", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS" }), signer: signer(CONSOLE_KEY) });
  assert.deepEqual(v(console1), { ok: true, reason: null, skipQueue: true, queueReason: null });
  const device1 = R.mintReceipt({ ...base(), signer: signer() });
  assert.deepEqual(v(device1), { ok: true, reason: null, skipQueue: false, queueReason: "keySource device" });
  assert.equal(v(R.mintReceipt({ ...base({ keySource: "helper" }), signer: signer(HELPER_KEY) })).skipQueue, true);
  // Key binding: the device key claiming console or helper is refused; the console key with basis allowed is queued.
  assert.deepEqual(v(R.mintReceipt({ ...base({ basis: "approved", keySource: "console", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS" }), signer: signer(KEY) })), { ok: false, reason: "bad_basis", skipQueue: false, queueReason: "invalid receipt" });
  assert.deepEqual(v(R.mintReceipt({ ...base({ keySource: "helper" }), signer: signer(KEY) })), { ok: false, reason: "bad_basis", skipQueue: false, queueReason: "invalid receipt" });
  assert.deepEqual(v(R.mintReceipt({ ...base({ keySource: "console" }), signer: signer(CONSOLE_KEY) })), { ok: true, reason: null, skipQueue: false, queueReason: "basis allowed" });
  assert.equal(v(R.mintReceipt({ ...base({ keySource: "helper" }), signer: signer(HELPER_KEY) }), { keys: [{ ...pin(HELPER_KEY, "helper"), keySource: undefined }] }).reason, "bad_basis", "a pinned key without a keySource trusts nothing");
  assert.equal(v(console1, { aud: "hub-other" }).reason, "wrong_aud");
  assert.equal(v(console1, { tool: "dissolve_agent" }).reason, "wrong_tool");
  assert.equal(v(console1, { input: { ...ARGS, command: "id" } }).reason, "args_mismatch");
  assert.equal(v(console1, { input: { ...ARGS, _moorai: { receipt: console1 } } }).ok, true, "the hub drops _moorai before hashing");
  assert.equal(v(console1, { nowSec: NOW + 60 }).reason, "expired");
  assert.equal(v(console1, { nowSec: NOW - 120 }).reason, "not_yet_valid");
  assert.equal(v(console1, { keys: [] }).reason, "unknown_key");
  const [p64, s64] = console1.split(".");
  const flipped = Buffer.from(s64, "base64url"); flipped[0] ^= 1;
  assert.equal(v(`${p64}.${flipped.toString("base64url")}`).reason, "bad_signature");
  assert.equal(v("nodot").reason, "malformed");
  assert.equal(v(`${p64}=.${s64}`).reason, "malformed");
  const seen = new Set();
  assert.equal(v(console1, { seen }).ok, true);
  assert.equal(v(console1, { seen }).reason, "replay");
  // The nonce and the approvalId are EACH single-use: one approval runs exactly one action.
  const sameApproval = R.mintReceipt({ ...base({ basis: "approved", keySource: "console", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS", nonce: "f".repeat(32) }), signer: signer(CONSOLE_KEY) });
  assert.deepEqual(v(sameApproval, { seen }), { ok: false, reason: "replay", skipQueue: false, queueReason: "invalid receipt" }, "same approvalId, new nonce");
  assert.equal(v(sameApproval, { seen: new Set(["nonce:" + "0".repeat(32)]) }).ok, true, "an unseen approvalId and nonce pass");
  const dev = new Set();
  assert.equal(v(R.mintReceipt({ ...base(), signer: signer() }), { seen: dev }).ok, true);
  assert.equal(v(R.mintReceipt({ ...base({ nonce: "e".repeat(32) }), signer: signer() }), { seen: dev }).ok, true, "receipts without an approvalId share no approvalId slot");
  assert.equal(v(R.mintReceipt({ ...base({ nonce: "e".repeat(32), keySource: "helper" }), signer: signer(HELPER_KEY) }), { seen: dev }).reason, "replay", "a seen nonce is refused whatever the approvalId");
  // A payload signed but not in canonical form is refused.
  const loose = Buffer.from(JSON.stringify(JSON.parse(Buffer.from(p64, "base64url").toString()), null, 1));
  const looseSig = edSign(null, Buffer.concat([Buffer.from(R.SIGN_PREFIX), loose]), CONSOLE_KEY);
  assert.equal(v(`${loose.toString("base64url")}.${looseSig.toString("base64url")}`).reason, "not_canonical");
  // A signed payload with exp - iat over 120.
  const longP = { ...JSON.parse(Buffer.from(p64, "base64url").toString()), exp: NOW + 121 };
  const longB = Buffer.from(canonicalJson(longP));
  assert.equal(v(`${longB.toString("base64url")}.${edSign(null, Buffer.concat([Buffer.from(R.SIGN_PREFIX), longB]), CONSOLE_KEY).toString("base64url")}`).reason, "ttl_too_long");
  // Device + approved, signed: refused.
  const badP = { ...JSON.parse(Buffer.from(device1.split(".")[0], "base64url").toString()), basis: "approved", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS" };
  const badB = Buffer.from(canonicalJson(badP));
  assert.equal(v(`${badB.toString("base64url")}.${edSign(null, Buffer.concat([Buffer.from(R.SIGN_PREFIX), badB]), KEY).toString("base64url")}`).reason, "bad_basis");
  // Non-integer numbers: a valid receipt, but the hub queues.
  const fl = { ...ARGS, timeout: 1.5 };
  const flW = R.mintReceipt({ ...base({ basis: "approved", keySource: "console", approvalId: "apr_0123456789ABCDEFGHJKMNPQRS", input: fl }), signer: signer(CONSOLE_KEY) });
  assert.deepEqual(v(flW, { input: fl }), { ok: true, reason: null, skipQueue: false, queueReason: "non-integer number" });
  assert.equal(R.portableNumbers({ a: [1, 2, { b: 9007199254740991 }], c: true }), true);
  assert.equal(R.portableNumbers({ a: 9007199254740994 }), false);
  assert.equal(R.portableNumbers({ a: [0.5] }), false);
});

test("vectors: the committed file is exactly what the generator produces, and every case verifies as stated", () => {
  const file = JSON.parse(readFileSync(join(ROOT, "test", "fixtures", "approval-receipts", "vectors.json"), "utf8"));
  assert.deepEqual(file, buildVectors(), "regenerate with: node scripts/gen-receipt-vectors.mjs");
  const keys = file.hub.keys;
  const names = new Set();
  for (const c of file.cases) {
    names.add(c.name);
    const input = JSON.parse(c.argumentsJson);
    const r = R.verifyReceipt(input._moorai.receipt, { keys, aud: file.hub.aud, tool: c.tool, input, nowSec: file.hub.nowSec, seen: new Set(c.seen || []) });
    assert.equal(r.ok, c.expect.receiptValid, `${c.name}: ${JSON.stringify(r)}`);
    assert.equal(r.reason, c.expect.reason, c.name);
    assert.equal(r.skipQueue ? "skip-queue" : "queue", c.expect.hubAction, c.name);
    assert.equal(r.queueReason, c.expect.queueReason, c.name);
    if (c.payloadCanonical) {
      assert.equal(Buffer.from(c.wire.split(".")[0], "base64url").toString("utf8"), c.payloadCanonical, c.name);
      assert.equal(c.signingInput, R.SIGN_PREFIX + c.payloadCanonical, c.name);
      assert.equal(c.argsSha256, createHash("sha256").update(c.argsCanonical, "utf8").digest("hex"), c.name);
    }
  }
  for (const n of ["device-key-claims-console", "device-key-claims-helper", "console-key-basis-allowed", "console-approved", "console-approved-int-bool-approver", "helper", "device-allowed", "non-integer-float", "integer-above-2-53", "bad-signature", "expired", "wrong-aud", "args-mismatch", "model-injected", "device-approved", "ttl-too-long", "replay", "approval-id-reused", "wrong-tool"]) assert.ok(names.has(n), `vector ${n} present`);
  assert.deepEqual(keys.map((k) => k.keySource).sort(), ["console", "device", "helper"], "one pinned key per source");
  assert.equal(new Set(keys.map((k) => k.keyId)).size, 3);
  for (const k of keys) { assert.equal(Buffer.from(k.publicKey, "base64url").length, 32); assert.equal(file.keys[k.keySource].publicKey, k.publicKey); }
  for (const n of ["device-key-claims-console", "device-key-claims-helper", "console-key-basis-allowed"]) assert.equal(file.cases.find((c) => c.name === n).expect.hubAction, "queue", n);
});

import { decideHeld, emptyState } from "../cli/approval-routing.mjs";
import { receiptIntake, receiptAnswer, receiptRequest } from "../cli/receipt-step.mjs";

test("approval grant: the console receipt rides on the grant's first use only", () => {
  const rule = { id: "r1", label: "L", holds: ["block"], grant: "ttl" };
  const wire = `${"a".repeat(20)}.${"b".repeat(86)}`;
  const g = { requestId: "apr_0123456789ABCDEFGHJKMNPQRS", ruleId: "r1", actionHash: "h2:00", decision: "approve", grant: "ttl", validUntilMs: Date.now() + 60000, receipt: wire };
  const first = decideHeld({ rule, verdict: "block", actionHash: "h2:00", grants: [g], state: emptyState() });
  assert.equal(first.outcome, "allow");
  assert.equal(first.receipt, wire);
  const second = decideHeld({ rule, verdict: "block", actionHash: "h2:00", grants: [g], state: first.state });
  assert.equal(second.outcome, "allow");
  assert.equal(second.receipt, null, "spent at the hub after one use");
});

test("receipt answer: only a final allow to a listed tool carries a receipt; ask and deny never do", () => {
  const policy = { approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai", tools: ["run_*"] }], ttlSec: 60 } };
  const sg = signer();
  const intake = (ti, tool = "mcp__it-ai__run_command", rewrites = true) => receiptIntake({ event: "PreToolUse", tool, ti, policy, rewrites });
  assert.equal(receiptIntake({ event: "PreToolUse", tool: "mcp__it-ai__run_command", ti: ARGS, policy: {} }), null, "no policy field: nothing changes");
  assert.equal(receiptIntake({ event: "PostToolUse", tool: "mcp__it-ai__run_command", ti: ARGS, policy }), null);
  assert.equal(receiptIntake({ event: "PreToolUse", tool: "Bash", ti: ARGS, policy }), null);
  assert.equal(receiptIntake({ event: "PreToolUse", tool: "mcp__it-ai__run_command", ti: ARGS, policy, coach: true }), null);
  const a = receiptAnswer(intake(ARGS), { decision: "allow", signer: sg, nowSec: NOW, nonce: "c".repeat(32) });
  assert.equal(a.keySource, "device");
  assert.deepEqual(Object.keys(a.input).sort(), ["_moorai", "command", "device"]);
  assert.equal(R.verifyReceipt(a.input._moorai.receipt, { keys: pinned, aud: "hub-1", tool: "run_command", input: a.input, nowSec: NOW, seen: new Set() }).ok, true);
  for (const decision of ["ask", "deny"]) assert.deepEqual(receiptAnswer(intake(ARGS), { decision, signer: sg }), { input: null, keySource: null }, decision);
  const inj = { ...ARGS, _moorai: { receipt: "x.y" } };
  assert.deepEqual(receiptAnswer(intake(inj), { decision: "ask", signer: sg }), { input: ARGS, keySource: null }, "ask: stripped, no receipt");
  assert.deepEqual(receiptAnswer(intake(inj), { decision: "deny", signer: sg }), { input: null, keySource: null });
  assert.deepEqual(receiptAnswer(intake(inj, "mcp__it-ai__list_devices"), { decision: "allow", signer: sg }), { input: ARGS, keySource: null }, "unlisted tool: stripped");
  assert.notEqual(receiptAnswer(intake(inj), { decision: "allow", signer: sg }).input._moorai.receipt, "x.y");
  assert.deepEqual(receiptAnswer(intake(inj, undefined, false), { decision: "allow", signer: sg }), { input: null, keySource: null }, "no rewrite: nothing to send");
  const wire = `${"a".repeat(20)}.${"b".repeat(86)}`;
  assert.deepEqual(receiptAnswer(intake(ARGS), { decision: "allow", signer: sg, grant: { requestId: "apr_x", receipt: wire } }), { input: { ...ARGS, _moorai: { receipt: wire } }, keySource: "console" });
  assert.deepEqual(receiptAnswer(intake(ARGS), { decision: "ask", signer: sg, grant: { requestId: "apr_x", receipt: wire } }), { input: null, keySource: null });
  assert.deepEqual(receiptRequest(intake(ARGS)), { aud: "hub-1", tool: "run_command", argsSha256: R.argsSha256(ARGS) });
  assert.deepEqual(intake({ ...ARGS, _moorai: { a: 1 } }).ti, ARGS, "the judged input has no _moorai");
  assert.equal(receiptRequest(intake(ARGS, "mcp__it-ai__list_devices")), null);
});

import { stampAlertSeq, alertChainView } from "../cli/alert-seq.mjs";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";

test("alert chain: only the raw argsSha256 of approval.receiptRequest is outside the chain; aud and tool are chained", () => {
  const RAW = "a".repeat(64);
  const body = { category: "Approval requested", reasonCode: "APPROVAL_REQUESTED", approval: { v: 1, requestId: "apr_0123456789ABCDEFGHJKMNPQRS", receiptArgsDigest: "h2:0011223344556677" } };
  const req = (aud, extra = {}) => ({ ...body, approval: { ...body.approval, receiptRequest: { aud, tool: "run_command", argsSha256: RAW, ...extra } } });
  const view = alertChainView(req("hub-1"));
  assert.deepEqual(view.approval.receiptRequest, { aud: "hub-1", tool: "run_command" });
  assert.ok(!JSON.stringify(view).includes(RAW), "the chained view carries no raw argsSha256");
  assert.equal(req("hub-1").approval.receiptRequest.argsSha256, RAW, "the alert itself keeps it for delivery");
  const head = (a, d) => stampAlertSeq(structuredClone(a), { tenant: "t", dir: mkdtempSync(join(tmpdir(), `rr-${d}-`)) }).chainHead;
  // The console strips the raw hash and still checks the link.
  const stripped = { ...body, approval: { ...body.approval, receiptRequest: { aud: "hub-1", tool: "run_command" } } };
  assert.equal(head(req("hub-1"), "a"), head(stripped, "b"));
  // A tampered aud or tool breaks the link.
  assert.notEqual(head(req("hub-evil"), "c"), head(req("hub-1"), "d"), "a tampered aud fails chain verification");
  assert.notEqual(head(req("hub-1", { tool: "dissolve_agent" }), "e"), head(req("hub-1"), "f"), "a tampered tool fails chain verification");
});

test("actionHash input: canonical { argsSha256, aud, tool } — a tampered aud or tool changes it", () => {
  const h = R.argsSha256(ARGS);
  assert.equal(R.receiptActionHashInput("run_command", h, "hub-1"), `approval\u0000{"argsSha256":"${h}","aud":"hub-1","tool":"run_command"}`);
  assert.notEqual(R.receiptActionHashInput("run_command", h, "hub-2"), R.receiptActionHashInput("run_command", h, "hub-1"));
  assert.notEqual(R.receiptActionHashInput("dissolve_agent", h, "hub-1"), R.receiptActionHashInput("run_command", h, "hub-1"));
});

test("example hub tool list: the 19 tools a hub binds receipts to, none of the six it never accepts", () => {
  const NEVER = ["click", "type_text", "press_key", "upload_file", "download_file", "push_file"];
  assert.deepEqual([...R.HUB_EXCLUDED_TOOLS].sort(), [...NEVER].sort());
  assert.equal(R.HUB_RECEIPT_TOOLS.length, 19);
  for (const t of NEVER) assert.ok(!R.HUB_RECEIPT_TOOLS.includes(t), t);
  // The policy example in the spec and the README is the same list.
  for (const f of ["docs/approval-receipts.md", "README.md"]) {
    const md = readFileSync(join(ROOT, f), "utf8");
    const m = /<!-- example-approvalReceipts -->\s*```json\s*([\s\S]*?)```/.exec(md);
    assert.ok(m, `${f}: example block present`);
    const ex = JSON.parse(m[1]).approvalReceipts;
    const tools = ex.audiences.flatMap((a) => a.tools || []);
    assert.deepEqual(tools, [...R.HUB_RECEIPT_TOOLS], f);
    for (const t of NEVER) assert.ok(!tools.includes(t), `${f}: ${t}`);
    assert.ok(R.receiptPolicy(JSON.parse(m[1])), `${f}: the example validates`);
  }
});

test("an audience with no tools list covers every tool of its server except the six a hub never accepts", () => {
  const p = R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai" }] } });
  assert.deepEqual(R.matchAudience(p, "mcp__it-ai__run_command"), { aud: "hub-1", mcpServer: "it-ai", tool: "run_command" });
  assert.deepEqual(R.matchAudience(p, "mcp__it-ai__some_new_tool"), { aud: "hub-1", mcpServer: "it-ai", tool: "some_new_tool" });
  for (const t of R.HUB_EXCLUDED_TOOLS) assert.equal(R.matchAudience(p, `mcp__it-ai__${t}`), null, t);
  const g = R.receiptPolicy({ approvalReceipts: { v: 1, audiences: [{ aud: "hub-1", mcpServer: "it-ai", tools: ["*"] }] } });
  for (const t of R.HUB_EXCLUDED_TOOLS) assert.equal(R.matchAudience(g, `mcp__it-ai__${t}`), null, `glob: ${t}`);
});
